require_once dirname(__DIR__,2).'/evidence/_lib/model.php';
const VERSION='1.5.0';const ORIGIN='https://beyondspacetime.org';const ROOT='/research/';const SCHEMA='beyondspacetime.research-plan.v1';
function models():array{static $m;if($m!==null)return $m;$m=[];foreach(\lessons() as $id=>$l){$related=[];foreach(\records() as $r)if(in_array($id,$r['foundations'],true))$related[]=$r['id'];$m['foundation:'.$id]=['title'=>$l['title'],'kind'=>'foundation','id'=>$id,'params'=>$l['params'],'source'=>$l['source'],'limitation'=>$l['limitation'],'evidence'=>$related,'url'=>ORIGIN.'/foundations/'.$id.'/','control'=>$l['control']];}foreach(\specs() as $id=>$s){$p=[];foreach($s['params'] as $key=>$v)$p[]=['key'=>$key,'label'=>$v[0],'default'=>$v[1],'min'=>$v[2],'max'=>$v[3],'step'=>$v[4],'unit'=>''];$related=[];foreach(\records() as $r)if($r['workbench']===$id)$related[]=$r['id'];$m['evidence:'.$id]=['title'=>$s['title'],'kind'=>'evidence','id'=>$id,'params'=>$p,'source'=>\corpus()['source'],'description'=>$s['description'],'evidence'=>$related,'url'=>ORIGIN.'/evidence/workbench/'.$id.'/','control'=>match($id){'escape'=>['ratio'=>0],'wall'=>['loggap'=>-1,'ceiling'=>1.2],'anchors'=>['percent'=>0]}];}return $m;}
function plan(string $title,string $question,array $cases,array $evidence=[]):array{return ['schema'=>SCHEMA,'title'=>$title,'question'=>$question,'cases'=>array_map(fn($c)=>['label'=>$c[0],'model'=>$c[1],'parameters'=>(object)$c[2]],$cases),'evidence'=>$evidence];}
function presets():array{return [
'light'=>['title'=>'Photon energy versus group speed','description'=>'Keep the massless reference beside a positive-gap drag case and a zero-drag control.','plan'=>plan('Photon energy versus group speed','Can energy loss alone establish substantial slowing?',[['Zero-gap reference','foundation:light-slowing',['gap'=>0]],['Positive-gap trial','foundation:light-slowing',['gap'=>.2]],['Zero drag control','foundation:light-slowing',['gap'=>.2,'drag'=>0]]],['fixed-gap-drag','ceiling'])],
'escape'=>['title'=>'Coherent conversion and escape','description'=>'Compare reversible, critical and overdamped selected-mode cases.','plan'=>plan('Coherent conversion and escape','Which escape ratios guarantee continuous monotone total conversion?',[['Reversible control','evidence:escape',['ratio'=>0]],['Critical escape','evidence:escape',['ratio'=>4]],['Overdamped escape','evidence:escape',['ratio'=>16]]],['escape-criterion','escape-verification','phase-match'])],
'wall'=>['title'=>'Can the fixed-gap wall model cross?','description'=>'Compare the illustrative wall and a tiny gap with the independently computed escape criterion; do not conflate the mechanisms.','plan'=>plan('Fixed-gap wall feasibility','Do the necessary drag bounds overlap in the specified wall model?',[['Illustrative wall','evidence:wall',['loggap'=>-1,'ceiling'=>1.2]],['Small-gap wall','evidence:wall',['loggap'=>-12,'ceiling'=>1.2]],['Escape channel control','evidence:escape',['ratio'=>4]]],['wall-crossing','wall-bound','wall-certificate','escape-criterion'])],
'distances'=>['title'=>'Distance anchors and signed inference bias','description'=>'Compare unchanged calibration with a proposed reduction, then examine signed luminosity-distance bias separately.','plan'=>plan('Distance anchors and inference bias','How sensitive are geometric anchors to a hypothesized distance correction?',[['Unchanged calibration','evidence:anchors',['percent'=>0]],['Proposed five-percent reduction','evidence:anchors',['percent'=>5]],['Positive extinction','foundation:distance-inference',['extinction'=>1]],['Negative magnitude offset','foundation:distance-inference',['extinction'=>-1]]],['anchor-lmc','anchor-ngc','optical-map','joint-fit'])],
'clocks'=>['title'=>'Clocks, separation and causal speed','description'=>'Keep coordinate separation, relativistic relative velocity and physical clock counts separate.','plan'=>plan('Clocks and causal measurements','How do coordinate rates differ from locally measured quantities?',[['Rest reference','foundation:separation',['beta'=>0]],['Opposite velocities','foundation:separation',['beta'=>.9]],['Clock comparison','foundation:constant-time',['beta'=>.6]],['Proper interval','foundation:spacetime',['beta'=>.6]]],['moving-endpoints','causal-reach','ceiling'])]
];}
function encode($v):string{return json_encode($v,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE|JSON_PRESERVE_ZERO_FRACTION|JSON_THROW_ON_ERROR);}
function object($v,string $name):array{if(!is_array($v)||($v!==[]&&array_is_list($v)))throw new \InvalidArgumentException($name.' must be an object.');return $v;}
function keys(array $a,array $allowed,string $name):void{foreach($a as $k=>$v)if(!in_array($k,$allowed,true))throw new \InvalidArgumentException('Unexpected field in '.$name.': '.$k);}
function words($v,int $max,string $name):string{if(!is_string($v)||strlen($v)>$max||trim($v)===''||preg_match('/[\x00-\x1F\x7F]/',$v))throw new \InvalidArgumentException($name.' must be nonempty plain text, at most '.$max.' UTF-8 bytes.');return trim($v);}
function normalize(array $p):array{keys($p,['schema','title','question','cases','evidence'],'plan');if(($p['schema']??null)!==SCHEMA)throw new \InvalidArgumentException('Unsupported recipe schema.');$title=words($p['title']??null,160,'Title');$question=words($p['question']??null,600,'Question');$cases=$p['cases']??null;if(!is_array($cases)||!array_is_list($cases)||count($cases)<1||count($cases)>8)throw new \InvalidArgumentException('Choose 1–8 ordered cases.');$out=[];$model=models();foreach($cases as $i=>$c){$c=object($c,'Case');keys($c,['label','model','parameters'],'case');$label=words($c['label']??null,120,'Case label');$id=$c['model']??null;if(!is_string($id)||!isset($model[$id]))throw new \InvalidArgumentException('Unknown model in case '.($i+1));$raw=object($c['parameters']??[],'Parameters');$params=[];keys($raw,array_column($model[$id]['params'],'key'),'parameters');foreach($model[$id]['params'] as $s){$v=array_key_exists($s['key'],$raw)?$raw[$s['key']]:$s['default'];if((!is_int($v)&&!is_float($v))||!is_finite((float)$v)||$v<$s['min']||$v>$s['max'])throw new \InvalidArgumentException('Case '.($i+1).': invalid '.$s['key']);$params[$s['key']]=(float)$v;}$out[]=['label'=>$label,'model'=>$id,'parameters'=>$params];}$e=$p['evidence']??[];if(!is_array($e)||!array_is_list($e)||count($e)>26)throw new \InvalidArgumentException('Evidence must be a list of at most 26 known identifiers.');foreach($e as $id)if(!is_string($id)||!isset(\records()[$id]))throw new \InvalidArgumentException('Unknown evidence record.');$e=array_values(array_unique($e));sort($e,SORT_STRING);return ['schema'=>SCHEMA,'title'=>$title,'question'=>$question,'cases'=>$out,'evidence'=>$e];}
function provenance():array{$files=['foundations/_lib/model.php','foundations/_lib/lessons.json','evidence/_lib/model.php','evidence/_lib/ledger.json','research/_lib/model.php'];$h=[];foreach($files as $f)$h[$f]=hash_file('sha256',dirname(__DIR__,2).'/'.$f);return ['workspace_version'=>VERSION,'php_version'=>PHP_VERSION,'serialize_precision'=>ini_get('serialize_precision'),'source_files_sha256'=>$h,'source_manuscript'=>\corpus()['source'],'note'=>'Hashes identify the installed calculation and catalog files, not an independent audit or empirical validation.'];}
function evaluate(array $p,?callable $event=null):array{$p=normalize($p);$prov=provenance();$runs=[];$used=[];$comparisons=[];$refs=[];foreach($p['evidence'] as $r)$refs[$r]=['selected'];foreach($p['cases'] as $i=>$c){$name='case-'.($i+1);if($event)$event('STEP_STARTED',$name);$m=models()[$c['model']];$r=$m['kind']==='foundation'?\solve($m['id'],$c['parameters']):\calc($m['id'],$c['parameters']);foreach($r['metrics'] as $v)if(is_float($v['value'])&&!is_finite($v['value']))throw new \RuntimeException('Nonfinite metric');$run=['id'=>$name,'label'=>$c['label'],'model'=>$c['model'],'model_title'=>$m['title'],'url'=>$m['url'],'result'=>$r];if(isset($used[$c['model']])){$a=$runs[$used[$c['model']]];$diff=[];foreach($r['metrics'] as $j=>$v){$prev=$a['result']['metrics'][$j];if($prev['label']!==$v['label']||$prev['unit']!==$v['unit'])throw new \RuntimeException('Metric mismatch');$delta=is_numeric($prev['value'])&&is_numeric($v['value'])?$v['value']-$prev['value']:null;$diff[]=['label'=>$v['label'],'unit'=>$v['unit'],'reference'=>$prev['value'],'candidate'=>$v['value'],'delta'=>$delta];}$comparisons[]=['model'=>$c['model'],'reference_case'=>$a['id'],'candidate_case'=>$name,'metrics'=>$diff];}else $used[$c['model']]=$i;$runs[]=$run;foreach($m['evidence'] as $rid)$refs[$rid][]=$name;if($event)$event('STEP_FINISHED',$name);}$records=[];$gateIds=[];ksort($refs);foreach($refs as $id=>$links){$r=\records()[$id];$records[]=$r+['linked_by'=>array_values(array_unique($links)),'url'=>ORIGIN.'/evidence/ledger/'.$id.'/'];foreach($r['gates'] as $g)$gateIds[$g]=true;}$gates=array_values(array_filter(\corpus()['gates'],fn($g)=>isset($gateIds[$g['id']])));$out=['schema'=>'beyondspacetime.research-result.v1','recipe'=>$p,'recipe_sha256'=>hash('sha256',encode($p)),'provenance'=>$prov,'runs'=>$runs,'comparisons'=>$comparisons,'evidence'=>$records,'gates'=>$gates,'interpretation'=>'Differences are only calculated within the same model against its first case. Cross-model runs are independent controls, not a combined fit. No gate is marked passed by this workflow. No new empirical validation.'];$out['result_sha256']=hash('sha256',encode($out));return $out;}
function decode(string $raw):array{if(strlen($raw)>65536)throw new \InvalidArgumentException('Request exceeds 64 KiB.');return object(json_decode($raw,true,24,JSON_THROW_ON_ERROR),'Request');}
function catalog():array{return ['schema'=>'beyondspacetime.research-catalog.v1','version'=>VERSION,'models'=>models(),'presets'=>presets(),'records'=>array_values(\records()),'gates'=>\corpus()['gates'],'source'=>\corpus()['source'],'recipe_schema'=>SCHEMA,'max_cases'=>8,'api'=>ORIGIN.ROOT.'api/','protocol'=>ORIGIN.ROOT.'protocol/'];}
